#!/usr/bin/env node
/**
 * Build Gatekeeper — Report Renderer
 *
 * Turns run-build-gate.js's own JSON result straight into docs/build/build_<id>.md. No agent
 * writes anything into this pipeline — there is nothing to validate or merge here beyond the
 * script's own output, by design: this is the one report in the whole system that is 100%
 * machine-generated, end to end.
 *
 * Usage:
 *   node scripts/render-build-report.js --all
 *   node scripts/render-build-report.js --issue ISSUE-001
 */
const fs = require('fs');
const path = require('path');
const {
  OUT_DIR, OUT_README, rel, listStep2Fixes, resultPathFor, reportPathFor,
} = require('./lib/gate');

function statusOf(result) {
  if (result.refused) return 'Refused';
  return result.passed ? 'Passed' : 'Failed';
}

function render(id, title, result) {
  const out = [];
  out.push(`# Build Gate — ${id}`);
  out.push('');
  out.push(`## ${title}`);
  out.push('');
  out.push(`_Generated by scripts/render-build-report.js on ${new Date().toISOString().slice(0, 10)}. Gate run ${result.generatedAt || 'not recorded'}. Every line below comes straight from the gate script — nothing here is agent-written._`);
  out.push('');

  const status = statusOf(result);
  out.push('## At a glance');
  out.push('');
  out.push('| | |');
  out.push('|---|---|');
  out.push(`| **Status** | ${status} |`);
  out.push(`| **Modules built** | ${(result.modules || []).map((m) => `\`${m}\``).join(', ') || 'n/a'} |`);
  const depChanges = (result.dependencyChecks || []).filter((d) => d.added.length || d.removed.length);
  out.push(`| **Dependency changes detected** | ${depChanges.length ? `**yes** — ${depChanges.map((d) => d.module).join(', ')}` : 'no'} |`);
  out.push('');

  out.push('## 1. Build result');
  out.push('');
  if (result.refused) {
    out.push(`**Refused.** ${result.reason}`);
  } else if (!result.steps) {
    out.push(`Stopped at stage \`${result.stage}\` before any module build ran.`);
    out.push('');
    out.push('```');
    out.push(result.output);
    out.push('```');
  } else {
    out.push('| Module | Command | Exit code |');
    out.push('|---|---|---|');
    for (const s of result.steps) out.push(`| \`${s.module}\` | \`${s.command}\` | ${s.exitCode} |`);
    out.push('');
    out.push('<details><summary>Full output</summary>');
    out.push('');
    for (const s of result.steps) { out.push(`**${s.module}**`); out.push(''); out.push('```'); out.push(s.output); out.push('```'); out.push(''); }
    out.push('</details>');
  }
  out.push('');

  out.push('## 2. Dependency tree diff');
  out.push('');
  out.push('_Compares `mvn dependency:tree` captured before and after the patch is applied, in the '
    + 'same worktree — flags any dependency version the fix pulled in or removed that its plan did '
    + 'not call for._');
  out.push('');
  if (!result.dependencyChecks || !result.dependencyChecks.length) {
    out.push('_Not measured (build stopped before this stage)._');
  } else {
    for (const d of result.dependencyChecks) {
      out.push(`**${d.module}**`);
      out.push('');
      if (!d.added.length && !d.removed.length) {
        out.push('No dependency changes.');
      } else {
        if (d.added.length) { out.push('Added:'); d.added.forEach((l) => out.push(`- \`${l}\``)); }
        if (d.removed.length) { out.push('Removed:'); d.removed.forEach((l) => out.push(`- \`${l}\``)); }
      }
      out.push('');
    }
  }

  out.push('---');
  out.push('');
  out.push('Run inside an isolated `git worktree` — applied and removed, the real working tree was never touched.');
  out.push('');
  return out.join('\n');
}

const INDEX_MARKER = '<!-- AUTO-GENERATED TABLE — regenerated by render-build-report.js, do not hand-edit below this line -->';

function rewriteIndex() {
  if (!fs.existsSync(OUT_DIR)) return;
  const files = fs.readdirSync(OUT_DIR).filter((f) => /^build_.+\.md$/i.test(f)).sort();
  const rows = files.map((name) => {
    const text = fs.readFileSync(path.join(OUT_DIR, name), 'utf8');
    const id = name.replace(/^build_/i, '').replace(/\.md$/i, '');
    const title = /^##\s+(.+)$/m.exec(text);
    const status = /\|\s*\*\*Status\*\*\s*\|\s*([^|]+)\|/.exec(text);
    return { id, title: title ? title[1].trim() : '(untitled)', status: status ? status[1].trim() : 'unknown', file: name };
  });
  const existing = fs.existsSync(OUT_README) ? fs.readFileSync(OUT_README, 'utf8') : buildReadmeContract();
  const contract = existing.includes(INDEX_MARKER) ? existing.slice(0, existing.indexOf(INDEX_MARKER)) : existing.trimEnd() + '\n\n';
  const table = [INDEX_MARKER, ''];
  if (!rows.length) table.push('_No build gate runs yet._', '');
  else { table.push('| ID | Title | Status | Report |', '|---|---|---|---|'); for (const r of rows) table.push(`| ${r.id} | ${r.title} | ${r.status} | [${r.file}](./${r.file}) |`); table.push(''); }
  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(OUT_README, contract.trimEnd() + '\n\n' + table.join('\n'));
}

function buildReadmeContract() {
  return `# Build Gate — Step 2

Phase C step 2, second half: **build-gatekeeper** runs \`mvn verify\` for every fix Fixer drafted a
diff for (Compiled or Compile Failed alike — this gate compiles the module itself, independently of
Fixer's own separate check) inside an isolated \`git worktree\`, and diffs the dependency tree before
and after the patch. This is the one report in the whole pipeline with **no agent-authored content
at all** — every line comes straight from the gate script, by design (deterministic CI/CD execution,
not open-ended agentic reasoning).

## Known caveat

This machine's only JDK is newer than this project targets, and its Lombok version does not process
annotations reliably on it — a \`Failed\` report whose errors sit outside the fix's own changed files
(e.g. a missing Lombok-generated \`log\` field or getter) is very likely this pre-existing toolchain
mismatch, not the patch. Cross-check the error locations against the fix's file list before treating
a build failure as the patch's fault.

`;
}

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 1) { const a = argv[i]; if (a === '--issue' || a === '-i') args.issue = argv[++i]; else if (a === '--all' || a === '-a') args.all = true; }
  return args;
}

function renderOne(id) {
  const resultFile = resultPathFor(id);
  if (!fs.existsSync(resultFile)) throw new Error(`No gate result at ${rel(resultFile)}. Run run-build-gate.js --issue ${id} first.`);
  const result = JSON.parse(fs.readFileSync(resultFile, 'utf8'));

  const fixes = listStep2Fixes();
  const fix = fixes.find((f) => f.id === id) || { title: id };

  const target = reportPathFor(id);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, render(id, fix.title, result));
  return { id, status: statusOf(result), report: rel(target) };
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.all) {
    const targets = listStep2Fixes();
    const written = []; const skipped = [];
    for (const t of targets) {
      try { const r = renderOne(t.id); written.push(r); console.log(`${r.id.padEnd(10)} ${r.status.padEnd(10)} -> ${r.report}`); } catch (err) { skipped.push(t.id); console.error(`${t.id.padEnd(10)} SKIPPED  ${err.message.split('\n')[0]}`); }
    }
    rewriteIndex();
    console.log(`\nWrote ${written.length}/${targets.length} report(s).`);
    if (skipped.length) process.exitCode = 1;
    return;
  }
  if (!args.issue) throw new Error('Missing --issue or --all.');
  const r = renderOne(args.issue);
  rewriteIndex();
  console.log(`Build Gatekeeper — wrote ${r.report} (${r.status})`);
}

try { main(); } catch (err) { console.error('Rendering failed:', err.message); process.exit(1); }
